actual=list(diff(b,p))
print('"'delta',sorted(actual,key=lambda x:x[0])==sorted([(k['path'],k['before'],k['after']) for k in d['exactDelta']],key=lambda x:x[0]))
for k in 'taskContent taskContentEn solutionContent solutionContentEn'.split():
 for t,s in [('numbered block','\\n1.'),('materials','**Material 1')][:1 if k.startswith('solution') else 2]:
